package com.franco.desco.adapter.out.sqlserver.access;
import com.franco.desco.adapter.out.sqlserver.shared.*; import com.franco.desco.application.access.RoleCommands.*; import com.franco.desco.application.access.port.out.RolePersistencePort; import com.franco.desco.application.shared.*; import com.franco.desco.application.shared.pagination.PageResult; import com.franco.desco.domain.access.RoleModels; import org.springframework.jdbc.core.simple.SimpleJdbcCall; import org.springframework.stereotype.Component; import java.util.*;
@Component public class RoleSqlServerAdapter implements RolePersistencePort {
 private final SqlServerPaExecutor e; private final PaPayloadFactory f; private final SimpleJdbcCall list,get,create,update,disable,permissions;
 public RoleSqlServerAdapter(SqlServerPaFactory x,SqlServerPaExecutor e,PaPayloadFactory f){this.e=e;this.f=f;list=x.callWithResultSets("seg","PA_Rol_Sel_Listado","items");get=x.callWithResultSets("seg","PA_Rol_Sel_Detalle","rol","permisos","usuarios");create=x.call("seg","PA_Rol_Ins_Registro");update=x.call("seg","PA_Rol_Upd_Registro");disable=x.call("seg","PA_Rol_Upd_Deshabilitar");permissions=x.call("seg","PA_RolPermiso_Upd_Asignaciones");}
 public PersistenceResult<PageResult<RoleModels.Summary>> list(ListRoles c,SessionIdentity i,RequestMetadata m){int p=c.page().pagina(),s=c.page().tamanio();var rs=e.executeJsonMultiResult(list,f.forQuery(i,m,Map.of("paginacion",Map.of("pagina",p,"tamanoPagina",s))));return PaAdapterSupport.page(rs.raw(),rs.rows("items"),p,s,this::summary,"No se pudieron consultar los roles.");}
 public PersistenceResult<RoleModels.Detail> get(GetRole c,SessionIdentity i,RequestMetadata m){var rs=e.executeJsonMultiResult(get,f.forQuery(i,m,Map.of("rol",Map.of("rolId",c.rolId()))));if(!PaAdapterSupport.success(rs.raw()))return PersistenceResult.error(PaAdapterSupport.message(rs.raw(),"No se pudo consultar el rol."));var roleRow=rs.one("rol").orElse(null);if(roleRow==null)return PersistenceResult.error("El rol seleccionado no está disponible.");var ps=rs.rows("permisos").stream().map(r->new RoleModels.Permission(SqlValues.longValue(r,"permisoId"),SqlValues.string(r,"codigo"),SqlValues.string(r,"nombre"),SqlValues.string(r,"accion"),SqlValues.bool(r,"esSensible"),SqlValues.bool(r,"requiereMotivo"),SqlValues.string(r,"moduloCodigo"),SqlValues.string(r,"moduloNombre"),SqlValues.bool(r,"estado"))).toList();var us=rs.rows("usuarios").stream().map(r->new RoleModels.User(SqlValues.longValue(r,"usuarioId"),SqlValues.string(r,"nombreUsuario"),SqlValues.string(r,"numeroDocumento"),SqlValues.string(r,"empleado"),SqlValues.instant(r,"fechaDesde"),SqlValues.instant(r,"fechaHasta"),SqlValues.bool(r,"estado"))).toList();var role=new RoleModels.Summary(SqlValues.longValue(roleRow,"rolId"),SqlValues.string(roleRow,"codigo"),SqlValues.string(roleRow,"nombre"),SqlValues.string(roleRow,"descripcion"),SqlValues.bool(roleRow,"requiereSegundoFactor"),SqlValues.bool(roleRow,"esSistema"),SqlValues.bool(roleRow,"estado"),us.size(),ps.size());return PersistenceResult.ok(PaAdapterSupport.message(rs.raw(),"Rol consultado correctamente."),new RoleModels.Detail(role,ps,us));}
 public PersistenceResult<Long> create(CreateRole c,SessionIdentity i,RequestMetadata m){var out=e.executeJsonMutation(create,f.forWrite(i,m,c,Map.of("rol",map("codigo",c.codigo(),"nombre",c.nombre(),"descripcion",c.descripcion(),"requiereSegundoFactor",c.requiereSegundoFactor()))));return PaAdapterSupport.result(out,SqlValues.longValue(out,"nRolId"),"No se pudo crear el rol.");}
 public PersistenceResult<Void> update(UpdateRole c,SessionIdentity i,RequestMetadata m){var out=e.executeJsonMutation(update,f.forWrite(i,m,c,Map.of("rol",map("rolId",c.rolId(),"nombre",c.nombre(),"descripcion",c.descripcion(),"requiereSegundoFactor",c.requiereSegundoFactor()))));return PaAdapterSupport.result(out,null,"No se pudo actualizar el rol.");}
 public PersistenceResult<Void> disable(DisableRole c,SessionIdentity i,RequestMetadata m){var out=e.executeJsonMutation(disable,f.forWrite(i,m,c,Map.of("rol",map("rolId",c.rolId(),"motivo",c.motivo()))));return PaAdapterSupport.result(out,null,"No se pudo deshabilitar el rol.");}
 public PersistenceResult<Void> updatePermissions(UpdatePermissions c,SessionIdentity i,RequestMetadata m){List<Map<String,Object>> ids=c.permisoIds().stream().map(id->Map.<String,Object>of("permisoId",id)).toList();Map<String,Object> b=new LinkedHashMap<>();b.put("rol",map("rolId",c.rolId(),"motivo",c.motivo()));b.put("permisos",ids);var out=e.executeJsonMutation(permissions,f.forWrite(i,m,c,b));return PaAdapterSupport.result(out,null,"No se pudieron actualizar los permisos del rol.");}
 private RoleModels.Summary summary(Map<String,Object> r){return new RoleModels.Summary(SqlValues.longValue(r,"rolId"),SqlValues.string(r,"codigo"),SqlValues.string(r,"nombre"),SqlValues.string(r,"descripcion"),SqlValues.bool(r,"requiereSegundoFactor"),SqlValues.bool(r,"esSistema"),SqlValues.bool(r,"estado"),z(SqlValues.longValue(r,"usuariosActivos")),z(SqlValues.longValue(r,"permisosActivos")));}
 private static long z(Long x){return x==null?0:x;} private static Map<String,Object> map(Object...p){Map<String,Object>m=new LinkedHashMap<>();for(int x=0;x<p.length;x+=2)if(p[x+1]!=null)m.put((String)p[x],p[x+1]);return m;}
}
